runtime":false,"volatility":"s","bodySha256":"9d6beb5d7b14fc281798e1198d3816942ffe00e50be937af27153b00e5dc99ee","definitionSha256":"14a3b5ceafb56ccdf53c37920d507ae200f75e33878160f3a2737f0c04447adf","defaultExpressions":""},{"name":"own_accounting_definition_v1","signature":"public.own_accounting_definition_v1(jsonb,jsonb,jsonb)","argNames":["d","sources","baseline"],"result":"jsonb","language":"plpgsql","defaults":1,"config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"i","bodySha256":"a7d2391d89c5aabcc6f4e7e403219e6f1469e216d8967e1de33ac60b37d52d07","definitionSha256":"51c48502fdce5b5a3375a43097efc57a086c8c576b50f8d66094831cb00dbf0f","defaultExpressions":"NULL::jsonb"},{"name":"own_accounting_history_v1","signature":"public.own_accounting_history_v1(jsonb,jsonb)","argNames":["baseline","d"],"result":"void","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"i","bodySha256":"a6a1f8e07a02d621e731f21aa3ec91da4dd2168dc34764c2d130f60b8f927ebc","definitionSha256":"fea0a46f488caa8a65386f72e3bf0b1f10916a84a25485f928987c43a6c7d4f5","defaultExpressions":""},{"name":"own_accounting_current_v1","signature":"public.own_accounting_current_v1(jsonb)","argNames":["ctx"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"s","bodySha256":"9b079b5b4b80de2df9f33ac4eab9e6de687213418354a991edebad0944c4a3d2","definitionSha256":"806b53bc34cd537966ad6118bbc90388ed0f361128a71497107b76068bdbb5ba","defaultExpressions":""},{"name":"own_accounting_summary_v1","signature":"public.own_accounting_summary_v1(jsonb,public.own_payroll_accounting_event)","argNames":["ctx","e"],"result":"jsonb","language":"plpgsql","defaults":0,"config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"s","bodySha256":"3440ce8cc10080855e31f2c58111af6e9229301fbd635c50de5a08dc135d4d20","definitionSha256":"f9cc41d3690b2dfe4c